// Figma Plugin API script for the use_figma MCP tool (generated by build_figma_board.py).
// Builds: per category -> local color variables (tokens), swatches bound to them,
// a type-scale sample, and editable desktop/mobile wireframes of the 4 required screens.
const DATA = /*__DATA__*/[];
const created = [];

let FAM = 'Noto Sans JP';
try {
  await figma.loadFontAsync({ family: FAM, style: 'Regular' });
  await figma.loadFontAsync({ family: FAM, style: 'Bold' });
} catch (e) {
  FAM = 'Inter';
  await figma.loadFontAsync({ family: 'Inter', style: 'Regular' });
  await figma.loadFontAsync({ family: 'Inter', style: 'Bold' });
}

const rgb = (h) => {
  const n = parseInt(h.replace('#', ''), 16);
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 };
};
const solid = (h) => [{ type: 'SOLID', color: rgb(h) }];
const INK = '#1b1f24', MUTED = '#4b5563', LINE = '#c9ced6', PAPER = '#ffffff', CANVAS = '#f3f4f6';

function txt(s, size, bold, color, width) {
  const t = figma.createText();
  t.fontName = { family: FAM, style: bold ? 'Bold' : 'Regular' };
  t.characters = String(s);
  t.fontSize = size;
  t.fills = solid(color || INK);
  if (width) { t.resize(width, t.height); t.textAutoResize = 'HEIGHT'; }
  return t;
}
function al(dir, props) {
  const f = figma.createAutoLayout(dir, props || {});
  f.fills = [];
  return f;
}

// Clear placement to the right of existing content.
let maxX = 0;
for (const c of figma.currentPage.children) maxX = Math.max(maxX, c.x + c.width);

// Reusable wireframe block component (label as a TEXT component property).
let blockComp = null, blockKey = null;
try {
  blockComp = figma.createComponent();
  blockComp.name = 'wf/block';
  blockComp.layoutMode = 'VERTICAL';
  blockComp.paddingLeft = blockComp.paddingRight = 8;
  blockComp.paddingTop = blockComp.paddingBottom = 8;
  blockComp.primaryAxisSizingMode = 'AUTO';
  blockComp.counterAxisSizingMode = 'FIXED';
  blockComp.resize(200, 40);
  blockComp.cornerRadius = 6;
  blockComp.fills = solid('#eef1f5');
  blockComp.strokes = solid(LINE);
  blockComp.strokeWeight = 1;
  const bt = txt('Block', 11, false, INK, 184);
  blockComp.appendChild(bt);
  blockKey = blockComp.addComponentProperty('Label', 'TEXT', 'Block');
  bt.componentPropertyReferences = { characters: blockKey };
  blockComp.description = 'Wireframe content block. Label = what the region shows.';
  blockComp.x = maxX + 200; blockComp.y = -200;
  created.push(blockComp.id);
} catch (e) { blockComp = null; }

function block(label, width) {
  if (blockComp && blockKey) {
    const i = blockComp.createInstance();
    i.setProperties({ [blockKey]: label });
    i.resize(width, i.height);
    return i;
  }
  const f = al('VERTICAL', { paddingLeft: 8, paddingRight: 8, paddingTop: 8, paddingBottom: 8 });
  f.fills = solid('#eef1f5'); f.cornerRadius = 6;
  f.appendChild(txt(label, 11, false, INK, width - 16));
  return f;
}

function desktopWF(cat, screenName, blocks, accent) {
  const wf = al('VERTICAL', { name: `${cat.key} / ${screenName} / desktop`, itemSpacing: 0 });
  wf.primaryAxisSizingMode = 'FIXED'; wf.counterAxisSizingMode = 'FIXED';
  wf.resize(560, 340);
  wf.fills = solid(PAPER); wf.strokes = solid(LINE); wf.strokeWeight = 1; wf.cornerRadius = 8; wf.clipsContent = true;
  const head = al('HORIZONTAL', { name: 'header', paddingLeft: 12, paddingRight: 12, paddingTop: 8, paddingBottom: 8, itemSpacing: 12 });
  head.fills = solid(accent);
  wf.appendChild(head); head.layoutSizingHorizontal = 'FILL';
  head.appendChild(txt(`${cat.key} ｜ ${screenName}`, 12, true, '#ffffff'));
  const body = al('HORIZONTAL', { name: 'body', itemSpacing: 12, paddingLeft: 12, paddingRight: 12, paddingTop: 12, paddingBottom: 12 });
  wf.appendChild(body); body.layoutSizingHorizontal = 'FILL'; body.layoutSizingVertical = 'FILL';
  let contentW = 536;
  if (cat.nav === 'sidebar') {
    const side = al('VERTICAL', { name: 'sidebar', itemSpacing: 6, paddingLeft: 8, paddingRight: 8, paddingTop: 8, paddingBottom: 8 });
    side.fills = solid(CANVAS); side.cornerRadius = 6;
    body.appendChild(side); side.layoutSizingVertical = 'FILL';
    ['ダッシュボード', '操作', '結果', '設定'].forEach((n) => side.appendChild(txt(n, 10, n === screenName.slice(0, 2), MUTED)));
    contentW = 536 - 100;
  }
  const content = al('HORIZONTAL', { name: 'content', itemSpacing: 8, counterAxisSpacing: 8 });
  content.layoutWrap = 'WRAP';
  body.appendChild(content); content.layoutSizingHorizontal = 'FILL';
  const bw = Math.floor((contentW - 8) / 2) - 8;
  blocks.forEach((b) => content.appendChild(block(b, bw)));
  return wf;
}

function mobileWF(cat, screenName, blocks, accent) {
  const wf = al('VERTICAL', { name: `${cat.key} / ${screenName} / mobile`, itemSpacing: 8 });
  wf.primaryAxisSizingMode = 'FIXED'; wf.counterAxisSizingMode = 'FIXED';
  wf.resize(180, 340);
  wf.fills = solid(PAPER); wf.strokes = solid(LINE); wf.strokeWeight = 1; wf.cornerRadius = 16; wf.clipsContent = true;
  const head = al('HORIZONTAL', { name: 'header', paddingLeft: 10, paddingRight: 10, paddingTop: 8, paddingBottom: 8 });
  head.fills = solid(accent);
  wf.appendChild(head); head.layoutSizingHorizontal = 'FILL';
  head.appendChild(txt(cat.nav === 'top' ? '☰ ' + screenName : screenName, 10, true, '#ffffff'));
  const list = al('VERTICAL', { name: 'stack', itemSpacing: 6, paddingLeft: 8, paddingRight: 8 });
  wf.appendChild(list); list.layoutSizingHorizontal = 'FILL'; list.layoutSizingVertical = 'FILL';
  blocks.forEach((b) => list.appendChild(block(b, 164)));
  if (cat.nav === 'sidebar') {
    const nav = al('HORIZONTAL', { name: 'bottom-nav', paddingLeft: 8, paddingRight: 8, paddingTop: 6, paddingBottom: 6, itemSpacing: 8 });
    nav.fills = solid(CANVAS);
    wf.appendChild(nav); nav.layoutSizingHorizontal = 'FILL';
    ['ホーム', '操作', '結果', '設定'].forEach((n) => nav.appendChild(txt(n, 9, false, MUTED)));
  }
  return wf;
}

const board = al('HORIZONTAL', { name: 'UI/UX 4分類 — トークン & 画面構成ボード', itemSpacing: 48, paddingLeft: 48, paddingRight: 48, paddingTop: 48, paddingBottom: 48 });
board.fills = solid(CANVAS);
board.x = maxX + 200; board.y = 100;
created.push(board.id);

const varSummary = [];
for (const cat of DATA) {
  const col = al('VERTICAL', { name: `${cat.key} column`, itemSpacing: 20, paddingLeft: 24, paddingRight: 24, paddingTop: 24, paddingBottom: 24 });
  col.fills = solid(PAPER); col.cornerRadius = 16;
  board.appendChild(col);
  col.appendChild(txt(cat.title, 24, true, INK, 776));

  // Tokens -> local variables
  const colors = cat.colors.length ? cat.colors : [{ name: 'accent', hex: '#1f5fbf' }];
  const accentTok = colors.find((c) => /primary|accent|brand|action/i.test(c.name)) || colors[0];
  let coll = null, modeId = null;
  try {
    coll = figma.variables.createVariableCollection(`${cat.key} tokens`);
    modeId = coll.modes[0].modeId;
    coll.renameMode(modeId, 'light');
  } catch (e) { coll = null; }
  col.appendChild(txt('カラートークン（ローカル変数に登録・見本は変数にバインド）', 13, true, MUTED));
  const sw = al('HORIZONTAL', { name: 'swatches', itemSpacing: 12, counterAxisSpacing: 12 });
  sw.layoutWrap = 'WRAP';
  col.appendChild(sw); sw.layoutSizingHorizontal = 'FILL';
  let nVars = 0;
  for (const c of colors) {
    const cell = al('VERTICAL', { name: `swatch/${c.name}`, itemSpacing: 4 });
    const r = figma.createRectangle();
    r.resize(88, 48); r.cornerRadius = 6; r.strokes = solid(LINE); r.strokeWeight = 1;
    let paint = { type: 'SOLID', color: rgb(c.hex) };
    if (coll) {
      try {
        const v = figma.variables.createVariable(`color/${c.name}`, coll, 'COLOR');
        v.scopes = ['FRAME_FILL', 'SHAPE_FILL', 'TEXT_FILL', 'STROKE_COLOR'];
        v.setValueForMode(modeId, { ...rgb(c.hex), a: 1 });
        paint = figma.variables.setBoundVariableForPaint(paint, 'color', v);
        nVars++;
      } catch (e) { /* keep raw paint */ }
    }
    r.fills = [paint];
    cell.appendChild(r);
    cell.appendChild(txt(c.name, 10, true, INK, 88));
    cell.appendChild(txt(c.hex, 10, false, MUTED, 88));
    sw.appendChild(cell);
  }
  varSummary.push({ key: cat.key, variables: nVars });

  // Type scale
  col.appendChild(txt('タイポグラフィ', 13, true, MUTED));
  const sizes = cat.sizes.length ? cat.sizes : [{ name: 'body', px: 16 }, { name: 'h2', px: 24 }, { name: 'h1', px: 32 }];
  const ts = al('VERTICAL', { name: 'type-scale', itemSpacing: 4 });
  col.appendChild(ts);
  sizes.forEach((s) => ts.appendChild(txt(`${s.name} ${s.px}px  空気質とLCAの計算結果 Aa 123`, Math.min(s.px, 36), s.px >= 20, INK)));

  // Screens
  col.appendChild(txt('4画面 × デスクトップ / モバイル（編集可能なワイヤーフレーム）', 13, true, MUTED));
  for (const [screenName, blocks] of Object.entries(cat.screens)) {
    const row = al('HORIZONTAL', { name: `${cat.key} / ${screenName}`, itemSpacing: 16 });
    col.appendChild(row);
    row.appendChild(desktopWF(cat, screenName, blocks, accentTok.hex));
    row.appendChild(mobileWF(cat, screenName, blocks, accentTok.hex));
  }
}

const shot = await board.screenshot();
return { createdNodeIds: created, boardId: board.id, componentId: blockComp ? blockComp.id : null, font: FAM, variables: varSummary, size: { w: board.width, h: board.height } };
